select a.romaneio_produto, isnull(c.pedido,c.item_caedu) as pedido
from LOJA_ENTRADAS a
inner join LOJA_ENTRADAS_PRODUTO b 
	on b.ROMANEIO_PRODUTO=a.ROMANEIO_PRODUTO and b.FILIAL=a.FILIAL
inner join FATURAMENTO_PROD c on c.NF_SAIDA=a.NUMERO_NF_TRANSFERENCIA and c.FILIAL=a.filial_origem
where isnull(c.pedido,c.item_caedu) not like 'CX%'
and len(isnull(c.pedido,c.item_caedu))>=6
